import{icon as ic}from'./icons.js';
import {VERSION,MODEL,COLORS,makeState,price,mark,nav,validateBasket,createBasket,operate,claim,portfolio,tokenValue,sharePayload,importBasket,sharesForBudget} from './engine.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>v===null||!Number.isFinite(v)?'—':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(v),num=(v,d=4)=>Number(v).toLocaleString('en-US',{maximumFractionDigits:d}),pct=v=>v===null?'—':`${v>=0?'+':''}${v.toFixed(2)}%`;
const KEY='elyset-rh-paper-v3';let state,registry=[],storageError='',route='',selected='ai-chips',period='1D',filter='All baskets',sort='default',query='',tokenQuery='',week=0,menu=false,tradeMode='buy',tradeQty='1',reviewOrder=null,previewDraft=null,tradeUnit='usd',tradeBudget='100',draftUndo=null;
try{const x=JSON.parse(localStorage.getItem(KEY));state=x?.version===VERSION&&Array.isArray(x.baskets)?x:makeState();}catch{state=makeState();storageError='Browser storage is unavailable. Progress lasts for this session only.';}
let draft={name:'',symbol:'',thesis:'',maxSupply:1000,assets:[{symbol:'NVDA',weight:50},{symbol:'AMD',weight:50}]};try{const d=JSON.parse(localStorage.getItem(KEY+'-draft'));if(d)draft=d;}catch{}
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));localStorage.setItem(KEY+'-draft',JSON.stringify(draft));}catch{storageError='Could not save to this browser. Keep this tab open to retain your session.';}};
const brandMark='<svg class="brand-mark" viewBox="0 0 32 32" aria-hidden="true"><path d="M4 5h9v5H9v12h14V10h-4V5h9v22H4z" fill="currentColor"/><path d="M13 13h6v5h-6z" fill="#dfff56"/></svg>';
const btn=(text,action,cls='',data='',disabled=false)=>`<button class="btn ${cls}" data-action="${action}" ${data} ${disabled?'disabled':''}>${text}</button>`;
const navlink=(id,label)=>`<a href="#${id}" class="nav-item ${route===id?'active':''}">${ic(id)}<span>${label}</span>${id==='portfolio'?'<small>PAPER</small>':''}</a>`;
const badge=(label,cls='')=>`<span class="badge ${cls}">${label}</span>`;
function notify(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function go(id){location.hash=id;}
function header(title,sub='',label=''){return `<div class="page-heading">${label?`<div class="eyebrow">${label}</div>`:''}<h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>`;}
function artwork(){let blocks='';const cube=(x,y,h,top,side)=>`<path d="M${x} ${y}l54-29 54 29-54 29z" fill="${top}"/><path d="M${x} ${y}v${h}l54 29v-${h}z" fill="${side}"/><path d="M${x+54} ${y+29}l54-29v${h}l-54 29z" fill="${side}" opacity=".86"/>`;for(let r=0;r<3;r++)for(let c=0;c<3;c++){const h=40+(r===1&&c===1?95:r===0?55:0);blocks+=`<g stroke="#3d4038" stroke-width=".7">${cube(128+c*54-r*54,245+c*29+r*29-h,h,(r===1&&c===1)?'#a079e6':r===0&&c===2?'#dfff56':'#d1d4cc',(r===1&&c===1)?'#9870df':r===0&&c===2?'#dfff56':'#33362e')}</g>`;}
return `<svg class="structure" viewBox="0 0 480 380" role="img" aria-label="Isometric blocks representing a basket of underlying assets"><defs><pattern id="grid" width="24" height="24" patternUnits="userSpaceOnUse"><path d="M24 0H0V24" fill="none" stroke="#d9dbd1" stroke-width=".55"/></pattern><pattern id="scan" width="4" height="4" patternUnits="userSpaceOnUse"><path d="M0 0h4" stroke="#f4f3ed" stroke-width=".3"/></pattern></defs><rect width="480" height="380" fill="url(#grid)"/><g fill="none" stroke="#aeb3a6" stroke-dasharray="2 7"><path d="m30 145 220-105 205 105-220 110zM85 40v300M420 50v270M20 290h435"/></g>${blocks}<path d="m30 180 250-140 180 100v210L250 380 30 250z" fill="url(#scan)" opacity=".35"/><g fill="none" stroke="#9970ea"><path d="m46 95 31-16 31 16v36l-31 17-31-17zM46 95l31 18 31-18M77 113v35m283-99 31-16 31 16v36l-31 17-31-17zM360 49l31 18 31-18M391 67v35"/></g><g fill="#dfff56"><path d="M400 250h24v24h-24zM424 226h24v24h-24z"/></g><g fill="#9970ea"><path d="M33 222h24v24H33zM57 246h24v24H57z"/></g><g stroke="#171a14"><path d="M42 35v14m-7-7h14M440 116v14m-7-7h14M385 340v14m-7-7h14"/></g><text x="17" y="20" font-size="9" fill="#53574d">ECOSYSTEM STRUCTURE / FIXED COMPOSITION</text><text x="17" y="370" font-size="9" fill="#53574d">ROBINHOOD CHAIN</text><text x="310" y="370" font-size="9" fill="#53574d">ONE SET. MANY ASSETS.</text></svg>`;}
function shell(body,standalone=false){return `${!standalone?`<aside class="sidebar ${menu?'expanded':''}"><a class="brand" href="#discover">${brandMark}<span class="brand-word">HOODSET<span class="brand-period">.</span><small>SETS ON ROBINHOOD CHAIN</small></span></a><div class="nav-label">WORKSPACE</div><nav aria-label="Main navigation">${navlink('discover','Discover')}${navlink('portfolio','My portfolio')}${navlink('onchain','Onchain baskets')}${navlink('watchlist','Watchlist')}${navlink('sectors','Sector leaderboard')}${navlink('tokens','Token universe')}${navlink('community','Community baskets')}</nav><div class="nav-label">THE DETAILS</div>${navlink('methodology','Methodology')}${navlink('data','Data & network')}<div class="thesis"><small>/ THE THESIS</small><h3>MANY ASSETS.<br>ONE CONVICTION.</h3><p>Build a set.<br>Know what backs every share.</p><a href="#methodology">How it works</a></div><a class="network" href="#data"><span class="network-icon">${ic('network')}</span><div>Robinhood Chain<small>4663 / ETH · reference</small></div></a><div class="side-foot">Independent design study. Demo only.</div></aside>`:''}<div class="${standalone?'community-shell':'workspace'}"><div class="${standalone?'community-top':'topbar'}">${standalone?`<a href="#${route.startsWith('basket/')?'community':'discover'}">${route.startsWith('basket/')?'Community baskets':'Back to HOODSET'}</a><span>Robinhood Chain ${badge('DEMO')}</span>`:`${btn(ic('menu'),'menu','mobile-menu',`aria-label="Toggle navigation" aria-expanded="${menu}"`)}<div class="breadcrumbs"><span>Robinhood Chain</span><b>/</b>${esc(({discover:'Discover',portfolio:'My portfolio',onchain:'Onchain baskets',watchlist:'Watchlist',sectors:'Sector leaderboard',tokens:'Token universe',methodology:'Methodology',data:'Data & network'})[route]||'Basket')}</div><div class="top-right"><a class="btn create-set" href="#community" aria-label="Create a basket">${ic('community')}<span>CREATE BASKET</span></a><span class="terminal-tag">▪ BASKET TERMINAL / RH</span><label class="search">${ic('search')}<input id="global-search" aria-label="Search baskets and tokens" placeholder="Search baskets, tokens…" value="${esc(query)}"><kbd>/</kbd></label>${btn(state.wallet?'DEMO WALLET':'START DEMO WALLET','wallet',state.wallet?'':'outline')}</div>`}</div><main id="main" class="${standalone?'community-main':''}">${storageError?`<div class="notice warn">${esc(storageError)}</div>`:''}<div class="demo-strip"><span><i></i> PAPER / DEMO · Scenario prices & charts · No real funds</span>${btn('Advance market','advance','text-btn','title="Advance the simulated market by one scenario step"')}</div>${state.fault.mode!=='fresh'?`<div class="notice warn">${esc(state.fault.symbol)} price ${esc(state.fault.mode)}. Affected basket valuations and price-based orders are paused. <a href="#data">Restore feed</a></div>`:''}${body}<footer><strong>HOODSET</strong><span>A Robinhood Chain design study. Fixed sets. Transparent mechanics.</span><a href="#data">Data & network</a></footer></main></div>`;}
function chart(b,{small=false}={}){if(nav(state,b)===null)return small?'<small>Price unavailable</small>':`<div class="chart-empty"><h3>PRICE UNAVAILABLE.</h3><p>Every component needs a valid mark. No assets have been excluded.</p><a href="#data">Check scenario feed</a></div>`;const span=({'1H':1,'1D':24,'1W':168,'1M':720})[period],end=state.step,start=Math.max(b.createdStep,end-span),values=Array.from({length:small?24:61},(_,i)=>{let t=start+(end-start)*i/((small?24:61)-1);return b.assets.reduce((v,a)=>v+a.qty*price(a.symbol,t),0);}),min=Math.min(...values)*.998,max=Math.max(...values)*1.002,w=small?150:800,h=small?42:225,points=values.map((v,i)=>`${i/(values.length-1)*(w-12)+6},${(1-(v-min)/(max-min))*(h-20)+8}`).join(' ');if(small)return `<svg class="sparkline" viewBox="0 0 ${w} ${h}" aria-hidden="true"><polyline points="${points}" stroke="#8c64d6" stroke-width="1.6" fill="none"/></svg>`;return `<div class="chart-wrap" tabindex="0" data-values="${values.join(',')}" data-start="${start}" data-end="${end}" data-min="${min}" data-max="${max}" aria-label="Inspect scenario chart. Use left and right arrow keys."><div class="chart-tooltip" hidden></div><svg viewBox="0 0 ${w} ${h+30}" role="img" aria-label="Simulated ${period} basket chart, ${money(values[0])} to ${money(values.at(-1))}"><defs><linearGradient id="fade" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#a17ae4" stop-opacity=".2"/><stop offset="1" stop-color="#a17ae4" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>`<line x1="0" y1="${i*(h-20)/3+8}" x2="800" y2="${i*(h-20)/3+8}" stroke="#d4d4cb" stroke-dasharray="3 5"/>`).join('')}<polygon points="6,${h} ${points} 794,${h}" fill="url(#fade)"/><polyline points="${points}" stroke="#9566df" stroke-width="2.2" fill="none"/><circle cx="794" cy="${points.split(' ').at(-1).split(',')[1]}" r="3" fill="#9566df"/><line class="chart-crosshair" x1="0" x2="0" y1="8" y2="${h}" stroke="#9566df" stroke-width="1" stroke-dasharray="3 4" visibility="hidden"/><circle class="chart-point" r="4" fill="#9566df" stroke="#faf9f5" stroke-width="2" visibility="hidden"/><text x="4" y="${h+22}" font-size="11" fill="#74796d">${start===end?'Created now':period+' scenario'}</text><text x="680" y="${h+22}" font-size="11" fill="#74796d">Step ${state.step}</text></svg></div>`;}
function periods(){return `<div class="segmented periods" aria-label="Chart time range">${['1H','1D','1W','1M'].map(p=>btn(p,'period',period===p?'active':'',`data-period="${p}" aria-pressed="${period===p}"`)).join('')}</div>`;}
function change(b){const n=nav(state,b),base=nav(state,b,b.createdStep);return n===null?null:(n/base-1)*100;}
function composition(b,full=false){const n=nav(state,b);return `<div class="composition"><div class="allocation-bar">${b.assets.map((a,i)=>`<span style="width:${n===null?a.weight:a.qty*mark(state,a.symbol)/n*100}%;background:${COLORS[i%COLORS.length]}"></span>`).join('')}</div>${b.assets.map((a,i)=>`<div class="constituent"><span class="token-mark" style="--token:${COLORS[i%COLORS.length]}">${esc(a.symbol.slice(0,2))}</span><div><strong>${esc(a.symbol)}</strong><small>${full?`${num(a.qty,8)} tokens / share`:esc(registry.find(r=>r.tokenSymbol===a.symbol)?.tokenName.replace(' • Robinhood Token','')||'Stock Token')}</small></div><div class="weight"><strong>${n===null?'—':num(a.qty*mark(state,a.symbol)/n*100,2)+'%'}</strong><small>${num(a.weight,2)}% initial</small></div></div>`).join('')}<div class="meta-pair"><span>Composition</span><strong>Fixed quantities</strong></div><div class="meta-pair"><span>Rebalancing</span><strong>None · weights drift</strong></div></div>`;}
function basketTable(baskets=state.baskets.filter(b=>!b.community),useFilters=true){let rows=baskets.filter(b=>!useFilters||((filter==='All baskets'||b.sector===filter)&&`${b.name} ${b.symbol} ${b.assets.map(a=>a.symbol).join(' ')}`.toLowerCase().includes(query.toLowerCase())));if(sort==='return')rows.sort((a,b)=>(change(b)??-Infinity)-(change(a)??-Infinity));if(sort==='name')rows.sort((a,b)=>a.name.localeCompare(b.name));if(sort==='assets')rows.sort((a,b)=>b.assets.length-a.assets.length);return `<div class="table-scroll"><table class="basket-table"><thead><tr><th aria-label="Watchlist"></th><th>BASKET</th><th>SHARE VALUE <small>DEMO USD</small></th><th>SINCE CREATION <small>SCENARIO</small></th><th>ASSETS</th><th>SCENARIO HISTORY</th><th></th></tr></thead><tbody>${rows.map(b=>`<tr><td><button class="star ${state.watch.includes(b.id)?'starred':''}" data-action="watch" data-id="${b.id}" aria-label="${state.watch.includes(b.id)?'Remove':'Add'} ${esc(b.name)} ${state.watch.includes(b.id)?'from':'to'} watchlist" aria-pressed="${state.watch.includes(b.id)}">${ic(state.watch.includes(b.id)?'star-filled':'watchlist')}</button></td><td><button class="basket-name" data-action="select" data-id="${b.id}"><span>${esc(b.name)}</span><small>${esc(b.symbol)} <em>${esc(b.sector)}</em></small></button></td><td>${money(nav(state,b))}<small>${nav(state,b)===null?'Price unavailable':'Fixed-composition share'}</small></td><td class="${(change(b)??0)<0?'negative':'positive'}">${pct(change(b))}<small>Simulated</small></td><td>${b.assets.length}<small>${b.assets.map(a=>esc(a.symbol)).join(' / ')}</small></td><td>${chart(b,{small:true})}</td><td>${btn('View','select','text-btn',`data-id="${b.id}" aria-label="View ${esc(b.name)}"`)}</td></tr>`).join('')}</tbody></table>${rows.length?'':`<div class="empty"><h3>NO BASKETS FOUND.</h3><p>Try another search or clear your filters.</p>${btn('Clear filters','clear')}</div>`}</div>`;}
function discover(){const b=state.baskets.find(b=>b.id===selected)||state.baskets[0],n=nav(state,b);return `<section class="hero"><div class="hero-copy"><div class="eyebrow">/01 — THE ROBINHOOD CHAIN BASKET TERMINAL</div><h1>YOUR THESIS.<br>ONE BASKET.</h1><strong class="highlight">STOCK TOKENS. SHARED CONVICTION.</strong><p>Turn a market view into a set of assets.<br>Fixed quantities. Clear backing. Your conviction.</p><div class="button-row"><a class="btn primary" href="#community">BUILD A BASKET</a><a class="link-violet" href="#discover" data-action="explore">Explore the sets</a></div></div><div class="hero-art">${artwork()}</div><div class="stats"><div><small>THEMATIC BASKETS</small><strong>6 <em>/ 6</em></strong><small>Explore every thesis</small></div><div><small>VERIFIED REGISTRY</small><strong>${registry.length} <em>tokens</em></strong><small>RH mainnet · checked Nov 26</small></div><div><small>PAPER BUYING POWER</small><strong>${money(state.cash)}</strong><small>Simulated USD · local progress</small></div><div><small>YOUR OWN ALLOCATION</small><strong class="condensed">Build your set</strong><a href="#community">2–12 assets · fixed composition</a></div></div></section><div class="section-label"><span>/02 <b>SCENARIO PERFORMANCE</b></span>${btn('Advance market','advance','text-btn')}</div><section class="featured" id="featured"><div class="featured-chart"><div class="flex-between"><div><h2>${esc(b.name)}</h2><small>${esc(b.symbol)} / ${esc(b.thesis)}</small></div><div class="button-row">${btn('Paper buy','trade','outline',`data-id="${b.id}"`,n===null)}${btn(ic(state.watch.includes(b.id)?'star-filled':'watchlist'),'watch','icon-btn',`data-id="${b.id}" aria-label="Toggle featured basket watchlist" aria-pressed="${state.watch.includes(b.id)}"`)}${btn(ic('share'),'share','icon-btn',`data-id="${b.id}" aria-label="Share basket"`)}</div></div><div class="chart-heading"><div><strong>${n===null?'—':num(n*10,2)} <em>pts</em></strong><span class="${(change(b)??0)<0?'negative':'positive'}">${pct(change(b))} <small>since creation / scenario</small></span></div>${periods()}</div>${chart(b)}<div class="chart-foot"><span>SIMULATED HISTORY · NOT MARKET PERFORMANCE</span><span>Base 1,000 / demo USD</span></div></div><div class="featured-composition"><h3>INSIDE THE BASKET</h3><p>${b.assets.length} assets. One thesis.</p>${composition(b)}${btn('VIEW ALL CONSTITUENTS','detail','wide',`data-id="${b.id}"`)}</div></section><section id="basket-section"><div class="section-label"><div><h2>/03 FIND YOUR CONVICTION <small>6</small></h2><p>One basket for every corner of the market.</p></div><select id="sort" aria-label="Sort baskets"><option value="default" ${sort==='default'?'selected':''}>Default order</option><option value="return" ${sort==='return'?'selected':''}>Scenario return</option><option value="name" ${sort==='name'?'selected':''}>Name A–Z</option><option value="assets" ${sort==='assets'?'selected':''}>Most assets</option></select></div><div class="filters">${['All baskets','AI & Chips','Technology','Emerging','Broad market','Finance','Consumer'].map(f=>btn(esc(f),'filter',filter===f?'active':'',`data-filter="${esc(f)}"`)).join('')}</div>${basketTable()}<div class="table-foot"><span>Transparent constituents. Fixed quantities. Paper trading only.</span><a href="#methodology">Read the methodology</a></div></section><section class="callout"><div><small>/04 — TEST YOUR THESIS.</small><h2>REAL CONVICTION.<br>PAPER CAPITAL.</h2><p>Start with $10,000 simulated USD. See how your thesis plays out.</p></div><a class="btn primary" href="#community">BUILD A BASKET</a></section>`;}
function positions(){const ps=Object.entries(state.positions).filter(([,p])=>p.qty>1e-10);return `<div class="section-label"><h2>YOUR POSITIONS <small>${ps.length}</small></h2><a href="#discover" class="btn">PAPER BUY</a></div>${ps.length?`<div class="table-scroll"><table><thead><tr><th>BASKET</th><th>SHARES</th><th>COST BASIS</th><th>CURRENT VALUE</th><th>UNREALIZED P&L</th><th></th></tr></thead><tbody>${ps.map(([id,p])=>{const b=state.baskets.find(b=>b.id===id),n=nav(state,b),v=n===null?null:n*p.qty;return `<tr><td><a class="table-name" href="#basket/${id}">${esc(b.name)}</a><small>${esc(b.symbol)}</small></td><td>${num(p.qty,6)}</td><td>${money(p.basis)}</td><td>${money(v)}</td><td class="${v!==null&&v-p.basis<0?'negative':'positive'}">${money(v===null?null:v-p.basis)}</td><td>${btn('Manage','trade','',`data-id="${id}"`)}</td></tr>`;}).join('')}</tbody></table></div>`:`<div class="empty"><div class="empty-symbol">+</div><h3>A LITTLE CONVICTION<br>GOES A LONG WAY.</h3><p>You have $10,000 simulated USD to explore.<br>Pick a basket to open your first paper position.</p><a class="btn primary" href="#discover">EXPLORE BASKETS</a></div>`}`;}
function history(){return `<div class="section-label"><div><h2>RECENT ACTIVITY</h2><p>Paper operations, with values recorded at execution.</p></div>${btn('Export CSV','export')}</div>${state.history.length?`<div class="table-scroll"><table><thead><tr><th>TIME</th><th>OPERATION</th><th>BASKET</th><th>SHARES</th><th>VALUE</th><th>REALIZED P&L</th></tr></thead><tbody>${state.history.slice(0,50).map(h=>`<tr><td>${new Date(h.at).toLocaleString('en-GB',{month:'short',day:'2-digit',hour:'2-digit',minute:'2-digit'})}<small>Scenario step ${h.step}</small></td><td>${badge(({buy:'BUY',sell:'SELL',withdraw:'WITHDRAW',reserve:'RESERVE',claim:'CLAIM'})[h.action],h.action==='buy'?'lime':'')}</td><td>${esc(h.name)}</td><td>${num(h.shares,6)}</td><td>${money(h.value)}</td><td>${h.realized==null?'—':money(h.realized)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="notice">Your first paper order will appear here.</div>'}`;}
function claims(id){const cs=state.claims.filter(c=>!c.claimed&&(!id||c.basketId===id));return `<div class="panel"><div class="flex-between"><h2>RESERVED EXITS</h2>${badge('PAPER')}</div><p>Reserved tokens no longer back outstanding shares. Claim them into your demo token wallet.</p>${cs.length?cs.map(c=>`<div class="claim-row"><div><strong>${esc(c.name)}</strong><small>${num(c.shares)} shares · ready in demo</small><small>${c.tokens.map(t=>`${num(t.qty,6)} ${esc(t.symbol)}`).join(' + ')}</small></div>${btn('Claim','claim','primary',`data-claim="${c.id}"`)}</div>`).join(''):'<div class="muted small">No reserved exits. Reserve part of a position to see a claim here.</div>'}</div>`;}
function tokenWallet(){const ts=Object.entries(state.tokens).filter(([,t])=>t.qty>1e-10);return `<div class="panel"><h2>YOUR UNDERLYING TOKENS</h2><p>Tokens received through in-kind withdrawal or reserve claims.</p>${ts.length?`<div class="table-scroll"><table><thead><tr><th>TOKEN</th><th>QUANTITY</th><th>DEMO VALUE</th></tr></thead><tbody>${ts.map(([s,t])=>`<tr><td>${esc(s)}</td><td>${num(t.qty,8)}</td><td>${money(mark(state,s)===null?null:t.qty*mark(state,s))}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted small">No tokens yet. Use Withdraw tokens on a basket position.</p>'}</div>`;}
function portfolioPage(){const p=portfolio(state);return `${header('MY PORTFOLIO <span class="title-badge">PAPER</span>','Simulated USD. Fixed-composition shares. Room to find your conviction.','YOUR THESIS, IN MOTION.')}<div class="portfolio-summary"><div><small>TOTAL PAPER VALUE</small><strong>${money(p.total)}</strong><span class="${(p.pnl??0)<0?'negative':'positive'}">${money(p.pnl)} all-time P&L</span></div><div class="summary-side"><div class="meta-pair"><span>Starting balance</span><strong>$10,000.00</strong></div><div class="meta-pair"><span>Buying power</span><strong>${money(state.cash)}</strong></div><div class="meta-pair"><span>Shares, tokens & reserves</span><strong>${money(p.invested)}</strong></div><small>All marked in demo USD</small></div></div>${!state.wallet?`<div class="notice flex-between"><span>Start a demo wallet to buy shares. No browser wallet or signature is required.</span>${btn('START DEMO WALLET','wallet','primary')}</div>`:''}${positions()}<div class="two-col secondary-grid">${tokenWallet()}${claims()}</div>${history()}<p class="footnote">Progress is stored in this browser. Fills exclude gas, fees, taxes and slippage. Seeded vault backing represents other simulated holders and is separate from your balance.</p>`;}
function watchlistPage(){const list=state.baskets.filter(b=>state.watch.includes(b.id));return `${header('YOUR CONVICTION.<br>ON WATCH.','Keep the narratives you care about in one place.','WATCHLIST')}<div class="section-label"><h2>WATCHING ${list.length}</h2><a href="#discover">Discover baskets</a></div>${list.length?basketTable(list,false):`<div class="empty"><div class="empty-symbol">${ic('watchlist')}</div><h3>A THESIS WORTH FOLLOWING.</h3><p>Star any basket to save it here.</p><a href="#discover" class="btn primary">EXPLORE BASKETS</a></div>`}`;}
function sectorsPage(){const bs=state.baskets.filter(b=>!b.community).sort((a,b)=>(change(b)??-Infinity)-(change(a)??-Infinity));return `${header('THE NARRATIVE<br>LEADERBOARD.','The leading basket in each sector, ranked by scenario return.','WHERE CONVICTION IS MOVING.')}<div class="notice">Scenario ranking only. These numbers illustrate the interface and are not historical returns or investment recommendations.</div><div class="table-scroll"><table><thead><tr><th>RANK</th><th>SECTOR / LEADING BASKET</th><th>SINCE CREATION</th><th>ASSETS</th><th></th></tr></thead><tbody>${bs.map((b,i)=>`<tr><td class="rank">${nav(state,b)===null?'—':String(i+1).padStart(2,'0')}</td><td><strong class="table-name">${esc(b.sector)}</strong><small>${esc(b.name)}</small></td><td class="positive">${pct(change(b))}<small>Simulated</small></td><td>${b.assets.length}</td><td><a href="#basket/${b.id}" class="btn">Explore</a></td></tr>`).join('')}</tbody></table></div><div class="callout"><h2>FIND THE BASKET<br>BEHIND YOUR THESIS.</h2><a href="#discover" class="btn primary">EXPLORE BASKETS</a></div>`;}
function tokensPage(){const rs=registry.filter(a=>`${a.tokenSymbol} ${a.tokenName}`.toLowerCase().includes(tokenQuery.toLowerCase()));return `${header('THE TOKEN UNIVERSE.','Contract-level transparency. Every asset has a verified identity.','KNOW WHAT IS INSIDE.')}<p>Active RH mainnet deployments from the official registry, checked November 26, 2026. Prices below are simulated. Registry presence does not establish swap liquidity or trading availability.</p><div class="section-label"><h2>ELIGIBLE ASSETS <small>${registry.length}</small></h2><label class="search bordered">${ic('search')}<input id="token-search" placeholder="Filter tokens…" aria-label="Filter tokens" value="${esc(tokenQuery)}"></label></div><div class="table-scroll"><table><thead><tr><th>TOKEN</th><th>CONTRACT · RH 4663</th><th>PRICE · DEMO USD</th><th>MULTIPLIER</th><th>PRICE SOURCE</th></tr></thead><tbody>${rs.map(a=>{const addr=a.deployments.find(d=>d.chainId===4663).contractAddress;return `<tr><td><strong>${esc(a.tokenSymbol)}</strong><small>${esc(a.tokenName.replace(' • Robinhood Token',''))}</small></td><td><a class="address" target="_blank" rel="noreferrer" href="https://robinhoodchain.blockscout.com/address/${addr}">${addr.slice(0,8)}…${addr.slice(-6)}</a></td><td>${money(mark(state,a.tokenSymbol))}</td><td>${num(+a.currentMultiplier,8)}<small>Registry snapshot</small></td><td>${badge(mark(state,a.tokenSymbol)===null?state.fault.mode.toUpperCase():'SCENARIO',mark(state,a.tokenSymbol)===null?'warn':'')}<small>Step ${state.step} · not live</small></td></tr>`;}).join('')}</tbody></table>${rs.length?'':'<div class="empty"><h3>NO MATCHING TOKENS.</h3><p>Try another symbol or company name.</p></div>'}</div>`;}
function syncTradeQuantity(b){if(tradeMode==='buy'&&tradeUnit==='usd')tradeQty=String(sharesForBudget(state,b,+tradeBudget));}
function tradeProblem(b){const q=+tradeQty,n=nav(state,b);if(['buy','sell'].includes(tradeMode)&&n===null)return 'A component price is unavailable. This order is paused.';if(!Number.isFinite(q)||q<.000001||q>1000000)return 'Enter an amount of at least 0.000001 shares.';if(tradeMode==='buy'&&n*q>state.cash+1e-8)return 'Not enough paper USD. Reduce the amount.';if(tradeMode==='buy'&&q+b.supply>b.maxSupply+1e-8)return 'This amount exceeds the maximum share supply.';if(tradeMode!=='buy'&&q>(state.positions[b.id]?.qty||0)+1e-10)return 'Amount exceeds your available shares.';return '';}
function tradeForm(b,compact=false){syncTradeQuantity(b);const qty=state.positions[b.id]?.qty||0,n=nav(state,b);return `<section class="panel order-panel"><div class="flex-between"><h2>${compact?'JOIN THIS BASKET':'BUILD YOUR POSITION'}</h2>${badge('DEMO','lime')}</div><div class="wallet-row"><span>${state.wallet?'Demo wallet active':'No wallet connected'}</span>${btn(state.wallet?'VIEW PORTFOLIO':'START DEMO WALLET',state.wallet?'portfolio':'wallet','outline')}</div>${!compact?`<label>BASKET<select id="onchain-basket" aria-label="Basket">${state.baskets.filter(x=>x.vault||x.community).map(x=>`<option value="${x.id}" ${x.id===b.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>`:''}<div class="meta-pair"><span>Your shares</span><strong>${num(qty,6)} ${esc(b.symbol)}</strong></div><div class="trade-tabs">${[['buy','Buy shares'],['sell','Sell'],['withdraw','Withdraw tokens'],['reserve','Reserve exit'],['claims','Claim']].map(([a,l])=>btn(l,'trade-mode',tradeMode===a?'active':'',`data-mode="${a}" aria-pressed="${tradeMode===a}"`)).join('')}</div>${tradeMode==='claims'?claims(b.id):`<div class="amount-heading"><span>${tradeMode==='buy'?'INVESTMENT AMOUNT':'SHARES TO EXIT'}</span>${tradeMode==='buy'?`<div class="segmented amount-units">${btn('USD','trade-unit',tradeUnit==='usd'?'active':'','data-unit="usd"')}${btn('Shares','trade-unit',tradeUnit==='shares'?'active':'','data-unit="shares"')}</div>`:''}</div><label class="trade-input-label"><span class="sr-only">${tradeMode==='buy'&&tradeUnit==='usd'?'Investment amount in USD':'Basket shares'}</span><div class="input-max"><input id="trade-qty" aria-label="${tradeMode==='buy'&&tradeUnit==='usd'?'Investment amount in USD':'Basket shares'}" type="number" min="${tradeMode==='buy'&&tradeUnit==='usd'?'.01':'.000001'}" step="any" value="${esc(tradeMode==='buy'&&tradeUnit==='usd'?tradeBudget:tradeQty)}">${btn('MAX','max','text-btn',`data-id="${b.id}"`)}</div></label>${tradeMode==='buy'?`<div class="quick-amounts">${[100,500,1000].map(v=>btn('$'+num(v,0),'quick-amount','',`data-amount="${v}"`)).join('')}</div>`:''}<div class="quote" id="quote">${quote(b)}</div><div class="notice small">${({buy:'Paper USD purchases the proportional backing and mints shares at the scenario mark.',sell:'Shares are burned for simulated USD. A real sale would require an executable swap route.',withdraw:'Burn shares and receive the exact underlying tokens. No swap or price-based settlement.',reserve:'Burn shares now. Proportional tokens move into a separate reserve until you claim them.'})[tradeMode]}</div><div id="trade-error" class="form-error" role="alert"></div>${btn('REVIEW PAPER OPERATION','review-order','primary wide',`data-id="${b.id}"`,!!tradeProblem(b))}<p class="footnote">No contract call. No real asset transfer. Demo reserves can be claimed immediately.</p>`}</section>`;}
function quote(b){const q=+tradeQty,n=nav(state,b),v=n===null||!Number.isFinite(q)||q<=0?null:n*q,problem=tradeProblem(b);return `<div class="order-feedback ${problem?'invalid':''}" role="status">${problem?esc(problem):tradeMode==='buy'?`You receive <strong>${num(q,8)} ${esc(b.symbol)}</strong>`:`${num(q,8)} ${esc(b.symbol)} will be burned`}</div><div class="meta-pair"><span>${tradeMode==='buy'?'Estimated cost':'Estimated value'}</span><strong>${money(v)}</strong></div><div class="meta-pair"><span>Backing / share</span><strong>${money(n)}</strong></div>${b.assets.map(a=>`<div class="meta-pair small"><span>${esc(a.symbol)}</span><span>${Number.isFinite(q)&&q>0?num(a.qty*q,8):'—'} tokens</span></div>`).join('')}${tradeMode==='buy'&&v!==null&&!problem?`<div class="meta-pair cash-after"><span>Paper USD after order</span><strong>${money(state.cash-v)}</strong></div>`:''}`;}
function redrawTrade(){const b=state.baskets.find(b=>b.id===selected);if($('#overlay .order-panel'))modal('PAPER BASKET OPERATION',tradeForm(b,true));else render();}
function updateTradeQuote(){const b=state.baskets.find(b=>b.id===selected);syncTradeQuantity(b);$('#quote').innerHTML=quote(b);const review=$('button[data-action="review-order"]');if(review)review.disabled=!!tradeProblem(b);const error=$('#trade-error');if(error)error.textContent='';}
function backing(b){const n=nav(state,b),cs=state.claims.filter(c=>!c.claimed&&c.basketId===b.id);return `<section class="panel"><div class="flex-between"><h2>PROOF OF BACKING</h2>${badge('SIMULATED')}</div><div class="backing-summary"><div><small>OUTSTANDING SHARES</small><strong>${num(b.supply,6)}</strong></div><div><small>BACKING VALUE</small><strong>${money(n===null?null:n*b.supply)}</strong></div></div><div class="table-scroll"><table><thead><tr><th>ASSET</th><th>VAULT BALANCE</th><th>PER SHARE</th></tr></thead><tbody>${b.assets.map(a=>`<tr><td>${esc(a.symbol)}</td><td>${num(a.qty*b.supply,8)}</td><td>${num(a.qty,8)}</td></tr>`).join('')}</tbody></table></div><div class="meta-pair"><span>Composition version</span><strong>1 / fixed</strong></div><div class="meta-pair"><span>Reserved exits</span><strong>${cs.length} · excluded above</strong></div><div class="meta-pair"><span>Maximum supply</span><strong>${num(b.maxSupply)}</strong></div><p class="footnote">Local accounting model. Seeded backing is simulated. No deployed vault or onchain balances are represented.</p></section>`;}
function onchainPage(){const b=state.baskets.find(x=>x.id===selected&&(x.vault||x.community))||state.baskets[0];selected=b.id;return `${header('YOUR THESIS.<br>ONCHAIN.','Underlying assets. Transparent backing. Proportional shares.','ASSET-BACKED BASKETS / DEMO')}<div class="notice flex-between"><div><h3>REDEEMABLE SHARES. DEMO SETTLEMENT.</h3><p>Explore the full vault flow using simulated USD and tokens. Real RH deployment and swap routes are not connected.</p></div><a href="#portfolio">Paper portfolio</a></div><div class="two-col">${tradeForm(b)}<div>${backing(b)}${claims(b.id)}</div></div><section class="callout"><div><small>THE RULES ARE PART OF THE PRODUCT.</small><h2>KNOW WHAT YOU OWN.</h2><p>Fixed token quantities. No automatic rebalancing. Reserve assets are segregated.</p></div><a href="#methodology" class="btn">READ THE RULES</a></section>`;}
function communityPage(){const cs=state.baskets.filter(b=>b.community),rank=[...cs].sort((a,b)=>(change(b)??-Infinity)-(change(a)??-Infinity));return `${header('BUILD IT. SHARE IT.','Choose your tokens and proportions. Create a fixed basket that others can inspect and try.','COMMUNITY / YOUR THESIS. YOUR SET.')}<section class="panel weekly"><div class="flex-between"><div><h2>WEEKLY LEADERBOARD</h2><p>Demo community sets ranked by simulated return per share.</p></div><div class="segmented">${btn('This week','week',week===0?'active':'','data-week="0"')}${btn('Last week','week',week===1?'active':'','data-week="1"')}</div></div>${week===1?'<div class="notice">No prior-week observations in this demo. Create a basket and advance the scenario.</div>':`<div class="community-ranks">${rank.map((b,i)=>`<a href="#basket/${b.id}"><span>${String(i+1).padStart(2,'0')}</span><strong>${esc(b.name)}</strong><span>${pct(change(b))}</span></a>`).join('')}</div>`}</section><div class="notice small">A basket fixes the quantities per share at creation. Market weights drift. A different allocation means a new basket. Your progress stays in this browser; basket links carry the composition for opening elsewhere.</div><div class="community-grid"><section class="panel builder"><div class="flex-between"><h2>CREATE A BASKET</h2>${badge('PAPER','lime')}</div><div class="builder-templates"><span>Start from a theme</span><div>${[['ai-chips','AI & Chips'],['big-tech','Big Tech'],['market-core','Market Core']].map(([id,label])=>btn(label,'template','',`data-template="${id}"`)).join('')}</div>${draftUndo?btn('Undo template','undo-template','text-btn'):''}</div><form id="basket-form"><label>NAME<input name="name" aria-label="Basket name" placeholder="Your ecosystem thesis" maxlength="48" value="${esc(draft.name)}" required></label><label>SHARE SYMBOL<input name="symbol" aria-label="Basket symbol" placeholder="e.g. MYSET" maxlength="8" value="${esc(draft.symbol)}" required></label><label>THESIS<textarea name="thesis" aria-label="Basket thesis" placeholder="What connects these assets?" maxlength="280" required>${esc(draft.thesis)}</textarea></label><div class="flex-between token-title"><h3>TOKENS & TARGET PROPORTIONS</h3>${btn('Equal weights','equal','text-btn')}</div><div id="builder-rows">${builderRows()}</div><div class="flex-between">${btn(ic('community')+' ADD TOKEN','add-token','', '',draft.assets.length>=12)}<span id="weight-total" class="weight-total">Total ${num(draft.assets.reduce((v,a)=>v+ +a.weight,0),2)}%</span></div><p class="small muted">Choose 2–12 eligible assets. Initial weights must total exactly 100%.</p><label>MAXIMUM SHARES<input type="number" name="maxSupply" aria-label="Maximum basket shares" min="1" max="1000000" value="${esc(draft.maxSupply)}" required></label><p class="footnote">One initial share is $100 in demo USD. Creation fixes token amounts at the current scenario mark and moves no investment funds.</p><div id="builder-error" class="form-error" role="alert"></div><button type="submit" class="btn primary wide">PREVIEW BASKET</button></form></section><section><div id="draft-preview">${draftPreview()}</div><div class="section-label"><h2>COMMUNITY SETS</h2><span>${cs.length}</span></div><div class="community-cards">${cs.map(b=>`<a class="community-card" href="#basket/${b.id}"><small>COMMUNITY / ${b.assets.length} TOKENS</small><h2>${esc(b.name)}</h2><p>${esc(b.thesis)}</p><div class="mini-allocation">${b.assets.map((a,i)=>`<span style="background:${COLORS[i]}">${esc(a.symbol)}</span>`).join('')}</div><div class="table-foot"><span>${esc(b.creator)}</span><span>Fixed composition</span></div></a>`).join('')}</div><div class="panel quiet"><h3>YOUR SET. YOUR RULES.</h3><p>Choose a thesis. Set the initial allocation. Share a link with the exact quantities.</p><a href="#methodology">Understand basket mechanics</a></div></section></div>`;}
function draftPreview(){const total=draft.assets.reduce((v,a)=>v+(+a.weight||0),0),valid=Math.abs(total-100)<1e-6;return `<section class="panel draft-preview"><div class="flex-between"><small>YOUR SET / LIVE PREVIEW</small>${badge('DRAFT')}</div><h2>${esc(draft.name||'YOUR NEXT SET.')}</h2><p>${esc(draft.thesis||'Choose your assets and see exactly what one share will contain.')}</p><div class="allocation-bar">${draft.assets.map((a,i)=>`<span style="width:${total?Math.max(0,+a.weight||0)/total*100:0}%;background:${COLORS[i%COLORS.length]}"></span>`).join('')}</div>${draft.assets.map((a,i)=>`<div class="draft-asset"><span class="asset-swatch" style="background:${COLORS[i%COLORS.length]}"></span><strong>${esc(a.symbol)}</strong><span>${num(+a.weight||0,2)}%</span><small>${mark(state,a.symbol)===null?'Price unavailable':num((+a.weight||0)/mark(state,a.symbol),8)+' tokens / share'}</small></div>`).join('')}<div class="draft-total ${valid?'complete':'invalid'}"><span>${valid?'Allocation complete':total>100?'Reduce allocation by '+num(total-100,2)+'%':'Allocate the remaining '+num(100-total,2)+'%'}</span><strong>${num(total,2)} / 100%</strong></div><div class="meta-pair"><span>Initial share</span><strong>$100.00 demo USD</strong></div><p class="footnote">Quantities become fixed when you create. Future weights drift with scenario prices.</p></section>`;}
function updateDraftPreview(){const el=$('#draft-preview');if(el)el.innerHTML=draftPreview();}
function builderRows(){return draft.assets.map((a,i)=>`<div class="builder-row"><label>TOKEN ${i+1}<select aria-label="Token ${i+1}" data-draft-token="${i}">${registry.map(r=>`<option value="${r.tokenSymbol}" ${a.symbol===r.tokenSymbol?'selected':''}>${r.tokenSymbol} / ${esc(r.tokenName.replace(' • Robinhood Token',''))}</option>`).join('')}</select></label><label>WEIGHT %<input type="number" min="0.01" max="100" step="any" aria-label="Token ${i+1} weight" data-draft-weight="${i}" value="${esc(a.weight)}"></label>${btn(ic('close'),'remove-token','icon-btn',`data-index="${i}" aria-label="Remove token ${i+1}"`,draft.assets.length<=2)}</div>`).join('');}
function basketPage(id){const b=state.baskets.find(b=>b.id===id);if(!b)return `${header('BASKET NOT FOUND.','This basket is not saved in this browser. Open its full shared link, or create a new set.')}<a href="#community" class="btn primary">COMMUNITY BASKETS</a>`;selected=b.id;return `${header(esc(b.name),esc(b.thesis),`${b.community?'COMMUNITY':'THEMATIC'} / FIXED COMPOSITION`)}<div class="basket-meta">${badge('DEMO / PAPER','lime')}<span>Creator ${esc(b.creator||'HOODSET demo')}</span><span>Composition v1 / ${esc(b.symbol)}</span>${btn('Copy link','share','text-btn',`data-id="${b.id}"`)}</div><div class="community-grid basket-detail"><div><section class="panel"><div class="flex-between"><h2>SCENARIO SHARE PERFORMANCE</h2>${periods()}</div><div class="chart-heading"><strong>${money(nav(state,b))} <em>/ share</em></strong><span class="positive">${pct(change(b))}</span></div>${chart(b)}<p class="footnote">Simulated marks, not observed market history. Creation step ${b.createdStep}; no pre-creation returns.</p></section><section class="panel"><h2>FIXED COMPOSITION</h2>${composition(b,true)}<p class="small muted">Targets describe creation. Token quantities stay fixed; current weights change with prices.</p></section>${backing(b)}</div><div>${tradeForm(b,true)}${claims(b.id)}<section class="panel quiet"><h3>HOLDER TOOLS</h3><p>Current weights, quantity per share and backing are available to everyone. No project token required.</p><a href="#portfolio">Open paper portfolio</a></section></div></div>`;}
function methodologyPage(){const texts=[['Eligibility comes first.','The demo allowlist contains 17 active Stock Tokens with chain 4663 deployments from Robinhood’s official asset registry, checked on November 26, 2026. An active token identity does not prove a usable swap route or sufficient liquidity.'],['A share is a fixed set of quantities.','At creation, one demo share is $100. Quantity per share = $100 × initial weight ÷ scenario token price. Quantities stay fixed. Current weight = quantity × current price ÷ basket value. No continuous rebalancing occurs.'],['Backing follows supply.','Buying shares adds their exact underlying quantities to simulated vault backing. Selling or withdrawing burns shares and removes proportional quantities. The initial backing shown on example vaults belongs to simulated other holders.'],['A missing price stays missing.','If one component is stale or unavailable, the whole basket loses its valuation. Price-based buys and sells stop; no component is silently dropped. In-kind exits still use fixed quantities and need no USD quote. Test this under Data & network.'],['Reserve now. Claim separately.','Reserve exit burns your shares and segregates the exact tokens from active backing. The reserve remains yours and stays included in portfolio value. Claim moves those tokens into your demo token wallet once, without minting additional value. Demo reserves are immediately claimable.'],['Paper is a model.','All USD balances, token prices, charts, returns, supply and operations are simulated and stored locally. Fills exclude fees, slippage, gas and tax. This prototype contains no deployed vault, real money entry, swap adapter or transaction signing.'],['A real integration needs separate checks.','RH REST bid/ask values represent the underlying equity and need currentMultiplier applied once for token-equivalent marks. The onchain Chainlink token feed already includes that adjustment. Feed freshness, halted assets, contract behavior and executable routes must be checked independently.']];return `${header('KNOW YOUR INDEX.','The rules, the sources and the decisions behind every set.','LESS TRUST. MORE TRANSPARENCY.')}<section class="method-intro"><small>THE HOODSET APPROACH</small><h2>A CLEAR VIEW OF<br>FIXED-COMPOSITION BASKETS.</h2><p>Start with a thesis, inspect every underlying asset and understand exactly what a share represents.</p></section><div class="method-grid">${texts.map(([h,p],i)=>`<article><span class="method-number">${String(i+1).padStart(2,'0')}</span><div><h3>${h}</h3><p>${p}</p></div></article>`).join('')}</div><section class="panel"><h2>CHECK THE SOURCE.</h2><div class="source-links"><a href="https://docs.robinhood.com/chain/connecting/" target="_blank" rel="noreferrer">Official network documentation</a><a href="https://api.robinhood.com/rhj/assets" target="_blank" rel="noreferrer">Official Stock Token registry</a><a href="https://docs.robinhood.com/chain/stock-token-apis/" target="_blank" rel="noreferrer">Stock Token APIs & multiplier</a><a href="https://docs.robinhood.com/chain/oracles-and-price-feeds/" target="_blank" rel="noreferrer">Oracles & price feeds</a></div></section>`;}
function dataPage(){return `${header('DATA, WITH<br>THE DETAILS.','Know the network. Know the source. Know the limits.','DATA & NETWORK')}<div class="two-col"><section class="panel"><h2>ROBINHOOD CHAIN</h2><div class="meta-pair"><span>Mainnet chain ID</span><strong>4663</strong></div><div class="meta-pair"><span>Testnet chain ID</span><strong>46630</strong></div><div class="meta-pair"><span>Gas token</span><strong>ETH</strong></div><div class="meta-pair"><span>Registry verified</span><strong>Nov 26, 2026</strong></div><div class="meta-pair"><span>Allowed Stock Tokens</span><strong>${registry.length}</strong></div><div class="meta-pair"><span>Wallet</span><strong>${state.wallet?'Demo wallet only':'Disconnected'}</strong></div><div class="meta-pair"><span>Contracts & swap routes</span><strong>Not connected</strong></div><p class="small">Network configuration is a verified reference. The prototype does not claim a live RPC connection.</p><a href="https://docs.robinhood.com/chain/connecting/" target="_blank" rel="noreferrer">Official network documentation</a></section><section class="panel"><h2>SCENARIO CONTROLS</h2><p>Change prices to see weights and P&L drift, or test a component failure.</p><div class="meta-pair"><span>Current market step</span><strong>${state.step}</strong></div>${btn('ADVANCE MARKET','advance','primary wide')}<label>COMPONENT<select id="fault-symbol" aria-label="Scenario component">${registry.map(a=>`<option ${state.fault.symbol===a.tokenSymbol?'selected':''}>${a.tokenSymbol}</option>`).join('')}</select></label><label>PRICE STATUS<select id="fault-mode" aria-label="Scenario price status"><option value="fresh" ${state.fault.mode==='fresh'?'selected':''}>Fresh scenario mark</option><option value="stale" ${state.fault.mode==='stale'?'selected':''}>Stale · pause affected orders</option><option value="missing" ${state.fault.mode==='missing'?'selected':''}>Missing · pause affected orders</option></select></label><p class="footnote">A failed component pauses the whole affected basket valuation. Fixed quantities stay visible.</p></section></div><section class="panel"><h2>PRICE & HISTORY MODEL</h2><p>All prices are deterministic scenario marks in demo USD. Charts use the same model as orders and weights. They are illustrative, never historical market performance. Corporate-action multipliers are displayed from the registry snapshot but are not applied to these already token-denominated scenario marks.</p><p>The official REST feed is not used for paper execution. A production adapter must apply the current multiplier to raw underlying bid/ask once, reject stale, missing or halted prices, and obtain separate executable swap quotes.</p></section><section class="panel"><h2>YOUR LOCAL PROGRESS</h2><p>Basket drafts, created sets, paper positions, reserves, history and watchlist are saved in this browser. A share link transfers only the basket’s composition, not balances or activity.</p><div class="button-row">${btn('Export paper state','export-state')}${btn('Reset demo…','reset','outline')}</div></section>`;}
async function render(){route=(location.hash.slice(1)||'discover').split('?')[0];menu=false;document.title=`${route.startsWith('basket/')?'Basket':({discover:'Discover',portfolio:'Paper portfolio',community:'Community baskets',onchain:'Onchain baskets',watchlist:'Watchlist',tokens:'Token universe',sectors:'Sector leaderboard',methodology:'Methodology',data:'Data & network'})[route]||'HOODSET'} | HOODSET`;const pages={discover,portfolio:portfolioPage,onchain:onchainPage,watchlist:watchlistPage,sectors:sectorsPage,tokens:tokensPage,community:communityPage,methodology:methodologyPage,data:dataPage};$('#app').innerHTML=shell(route.startsWith('basket/')?basketPage(route.split('/')[1]):pages[route]?.()||`${header('PAGE NOT FOUND.')}<a class="btn" href="#discover">Discover baskets</a>`,route==='community'||route.startsWith('basket/'));}
function closeModal(){$('#overlay').innerHTML='';document.body.classList.remove('modal-open');reviewOrder=null;previewDraft=null;}
function modal(title,body){$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="flex-between"><h2>${title}</h2>${btn(ic('close'),'close','icon-btn','aria-label="Close dialog"')}</div>${body}</section></div>`;document.body.classList.add('modal-open');$('#overlay button')?.focus();}
function openTrade(id){selected=id;tradeMode='buy';tradeQty='1';tradeUnit='usd';tradeBudget='100';const b=state.baskets.find(b=>b.id===id);modal('PAPER BASKET OPERATION',tradeForm(b,true));}
function syncDraft(){const f=$('#basket-form');if(!f)return;draft.name=f.elements.name.value;draft.symbol=f.elements.symbol.value.toUpperCase().replace(/[^A-Z0-9]/g,'');f.elements.symbol.value=draft.symbol;draft.thesis=f.elements.thesis.value;draft.maxSupply=f.elements.maxSupply.value;save();updateDraftPreview();}
function preview(){syncDraft();try{validateBasket(state,draft,registry.map(a=>a.tokenSymbol));previewDraft=structuredClone(draft);const data=previewDraft;modal('REVIEW YOUR BASKET',`<p class="eyebrow">FIXED COMPOSITION / DEMO ONLY</p><h3>${esc(data.name)} ${badge(esc(data.symbol),'lime')}</h3><p>${esc(data.thesis)}</p><table><thead><tr><th>ASSET</th><th>INITIAL WEIGHT</th><th>TOKENS / SHARE</th></tr></thead><tbody>${data.assets.map(a=>`<tr><td>${esc(a.symbol)}</td><td>${num(+a.weight,2)}%</td><td>${num(+a.weight/mark(state,a.symbol),8)}</td></tr>`).join('')}</tbody></table><div class="meta-pair"><span>Initial share value</span><strong>$100.00</strong></div><div class="meta-pair"><span>Maximum shares</span><strong>${num(+data.maxSupply)}</strong></div><div class="notice small">Creating this demo basket fixes quantities, stores it in your browser and moves no funds. It does not deploy a contract.</div><div id="creation-error" role="alert" class="form-error"></div>${btn('CREATE DEMO BASKET','create','primary wide')}`);previewDraft=data;}catch(e){$('#builder-error').textContent=e.message;}}
function review(id){try{const b=state.baskets.find(b=>b.id===id),amount=+tradeQty;const copy=structuredClone(state);operate(copy,id,tradeMode,amount);const n=nav(state,b);const order={id,action:tradeMode,amount,step:state.step};modal('REVIEW PAPER OPERATION',`<p>${esc(b.name)} / ${esc(b.symbol)}</p><div class="meta-pair"><span>Operation</span><strong>${({buy:'Buy shares',sell:'Sell',withdraw:'Withdraw tokens',reserve:'Reserve exit'})[tradeMode]}</strong></div><div class="meta-pair"><span>Shares</span><strong>${num(amount,8)}</strong></div><div class="meta-pair"><span>Scenario value</span><strong>${money(n===null?null:n*amount)}</strong></div>${b.assets.map(a=>`<div class="meta-pair"><span>${esc(a.symbol)}</span><strong>${num(a.qty*amount,8)} tokens</strong></div>`).join('')}<div class="notice small">This changes only your local paper ledger. No wallet signature, gas or real funds.</div><div id="confirm-error" class="form-error" role="alert"></div>${btn('CONFIRM PAPER OPERATION','confirm-order','primary wide')}`);reviewOrder=order;}catch(e){const el=$('#trade-error');if(el)el.textContent=e.message;else notify(e.message);}}
async function copyLink(id){const b=state.baskets.find(b=>b.id===id);const url=new URL(location.href);url.hash=`basket/${id}${b.community&&b.id!=='community-conviction'?'?set='+encodeURIComponent(sharePayload(b)):''}`;try{await navigator.clipboard.writeText(url.href);notify('Basket link copied. Composition only; no wallet data.');}catch{modal('BASKET LINK',`<p>Copy this link to open the same demo composition.</p><input aria-label="Basket link" readonly value="${esc(url.href)}">`);}}
function download(text,name,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;try{if(a==='close'){closeModal();return;}if(a==='menu'){menu=!menu;$('.sidebar')?.classList.toggle('expanded',menu);el.setAttribute('aria-expanded',String(menu));return;}if(a==='wallet'){if(state.wallet){go('portfolio');closeModal();return;}modal('START A DEMO WALLET',`<p>Explore with $10,000 paper USD and a local token wallet. Your trades, shares and reserves are simulated.</p><div class="notice small">No real wallet connection. No onchain address. No signature.</div>${btn('ACTIVATE DEMO WALLET','activate','primary wide')}`);return;}if(a==='activate'){state.wallet=true;save();closeModal();render();notify('Demo wallet active. $10,000 paper USD available.');return;}if(a==='portfolio'){closeModal();go('portfolio');return;}if(a==='advance'){state.step++;save();render();notify('Scenario advanced. Quantities stay fixed; prices and weights changed.');return;}if(a==='watch'){state.watch=state.watch.includes(id)?state.watch.filter(x=>x!==id):[...state.watch,id];save();render();return;}if(a==='share'){await copyLink(id);return;}if(a==='explore'){e.preventDefault();$('#basket-section')?.scrollIntoView({behavior:'smooth'});return;}if(a==='select'){const b=state.baskets.find(b=>b.id===id);if(route==='discover'){selected=id;period='1D';render();$('#featured').scrollIntoView({behavior:'smooth',block:'start'});}else go('basket/'+id);return;}if(a==='detail'){go('basket/'+id);return;}if(a==='period'){period=el.dataset.period;render();return;}if(a==='filter'){filter=el.dataset.filter;render();$('#basket-section')?.scrollIntoView({block:'start'});return;}if(a==='clear'){query='';filter='All baskets';sort='default';render();return;}if(a==='trade'){openTrade(id);return;}if(a==='trade-mode'){tradeMode=el.dataset.mode;tradeQty='1';if($('#overlay .order-panel')){const b=state.baskets.find(b=>b.id===selected);modal('PAPER BASKET OPERATION',tradeForm(b,true));}else render();return;}if(a==='trade-unit'){const b=state.baskets.find(b=>b.id===selected);if(el.dataset.unit==='usd'&&nav(state,b)!==null)tradeBudget=String(Math.round((+tradeQty||0)*nav(state,b)*100)/100);tradeUnit=el.dataset.unit;redrawTrade();return;}if(a==='quick-amount'){tradeUnit='usd';tradeBudget=el.dataset.amount;redrawTrade();return;}if(a==='max'){const b=state.baskets.find(b=>b.id===id),n=nav(state,b);if(tradeMode==='buy'){tradeUnit='usd';tradeBudget=String(n===null?0:Math.floor(Math.min(state.cash,(b.maxSupply-b.supply)*n)*100)/100);}else tradeQty=String(state.positions[id]?.qty||0);redrawTrade();return;}if(a==='review-order'){review(id);return;}if(a==='confirm-order'){if(!reviewOrder)return;const o=reviewOrder;if(o.step!==state.step)throw Error('The scenario changed. Review a new quote.');operate(state,o.id,o.action,o.amount);save();closeModal();render();notify('Paper operation completed. Portfolio and backing updated.');return;}if(a==='claim'){claim(state,el.dataset.claim);save();closeModal();render();notify('Reserve claimed into your demo token wallet.');return;}if(a==='template'){syncDraft();draftUndo=structuredClone(draft);const b=state.baskets.find(b=>b.id===el.dataset.template);draft.assets=b.assets.map(a=>({symbol:a.symbol,weight:a.weight}));draft.name=draft.name||b.name+' Set';draft.symbol=draft.symbol||('MY'+b.symbol).slice(0,8);draft.thesis=draft.thesis||b.thesis;save();render();return;}if(a==='undo-template'){if(draftUndo){draft=structuredClone(draftUndo);draftUndo=null;save();render();}return;}if(a==='equal'){syncDraft();const base=Math.floor(10000/draft.assets.length)/100;draft.assets.forEach((x,i)=>x.weight=i===draft.assets.length-1?+(100-base*(draft.assets.length-1)).toFixed(2):base);save();render();return;}if(a==='add-token'){syncDraft();if(draft.assets.length>=12)return;const r=registry.find(r=>!draft.assets.some(x=>x.symbol===r.tokenSymbol));if(r)draft.assets.push({symbol:r.tokenSymbol,weight:0});save();render();return;}if(a==='remove-token'){syncDraft();if(draft.assets.length>2)draft.assets.splice(+el.dataset.index,1);save();render();return;}if(a==='create'){if(!previewDraft)return;const b=createBasket(state,previewDraft,registry.map(a=>a.tokenSymbol));draftUndo=null;save();closeModal();draft={name:'',symbol:'',thesis:'',maxSupply:1000,assets:[{symbol:'NVDA',weight:50},{symbol:'AMD',weight:50}]};save();tradeMode='buy';go('basket/'+b.id);notify('Demo basket created. Its quantities are now fixed.');return;}if(a==='week'){week=+el.dataset.week;render();return;}if(a==='export'){const cols=['time','action','basket','shares','scenario_usd','realized_pnl'];const csv=[cols,...state.history.map(h=>[new Date(h.at).toISOString(),h.action,h.name,h.shares,h.value??'',h.realized??''])].map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\n');download(csv,'hoodset-paper-history.csv','text/csv');return;}if(a==='export-state'){download(JSON.stringify(state,null,2),'hoodset-paper-state.json');return;}if(a==='reset'){modal('RESET PAPER DEMO?',`<p>This clears this browser’s paper positions, created baskets, watchlist and history. Export your state first if you want to keep a copy.</p>${btn('RESET DEMO','confirm-reset','primary wide')}`);return;}if(a==='confirm-reset'){state=makeState();draftUndo=null;draft={name:'',symbol:'',thesis:'',maxSupply:1000,assets:[{symbol:'NVDA',weight:50},{symbol:'AMD',weight:50}]};save();closeModal();go('discover');render();notify('Paper demo reset.');return;}}catch(err){const target=$('#confirm-error')||$('#creation-error');if(target)target.textContent=err.message;else notify(err.message);}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='trade-qty'){if(tradeMode==='buy'&&tradeUnit==='usd')tradeBudget=t.value;else tradeQty=t.value;updateTradeQuote();return;}if(t.dataset.draftWeight!==undefined){draft.assets[+t.dataset.draftWeight].weight=t.value;const total=draft.assets.reduce((v,a)=>v+Number(a.weight),0);$('#weight-total').textContent='Total '+num(total,2)+'%';$('#weight-total').classList.toggle('invalid',Math.abs(total-100)>1e-6);save();updateDraftPreview();return;}if(t.closest('#basket-form')){syncDraft();return;}if(t.id==='global-search'){query=t.value;const start=t.selectionStart;if(route!=='discover'){go('discover');}else{render();const f=$('#global-search');f.focus();f.setSelectionRange(start,start);}return;}if(t.id==='token-search'){tokenQuery=t.value;const start=t.selectionStart;render();const f=$('#token-search');f.focus();f.setSelectionRange(start,start);}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.draftToken!==undefined){draft.assets[+t.dataset.draftToken].symbol=t.value;save();updateDraftPreview();}if(t.id==='sort'){sort=t.value;render();$('#basket-section').scrollIntoView({block:'start'});}if(t.id==='onchain-basket'){selected=t.value;tradeQty='1';render();}if(t.id==='fault-symbol'||t.id==='fault-mode'){state.fault={symbol:$('#fault-symbol').value,mode:$('#fault-mode').value};save();render();}});
document.addEventListener('submit',e=>{if(e.target.id==='basket-form'){e.preventDefault();preview();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)){e.preventDefault();$('#global-search')?.focus();}if(e.key==='Tab'&&$('#overlay .modal')){const list=[...$('#overlay').querySelectorAll('button:not(:disabled),input,a[href],select,textarea')];if(!list.length)return;const first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>{closeModal();render();window.scrollTo(0,0);});
async function init(){try{const r=await fetch('./assets/registry.json');if(!r.ok)throw Error('Registry snapshot unavailable.');registry=(await r.json()).assets.filter(a=>a.tokenSymbol in MODEL);if(!registry.length)throw Error('No eligible assets in registry snapshot.');const payload=location.hash.split('?set=')[1];if(payload){try{const b=importBasket(state,decodeURIComponent(payload),registry.map(a=>a.tokenSymbol));save();window.history.replaceState(null,'','#basket/'+b.id);}catch(e){notify(e.message);location.hash='community';}}render();}catch(e){$('#app').innerHTML=`<main class="load-error"><h1>DATA UNAVAILABLE.</h1><p>${esc(e.message)} Reload to load the bundled registry.</p><button class="btn" onclick="location.reload()">Reload</button></main>`;}}
init();

function inspectChart(el,index){const values=el.dataset.values.split(',').map(Number),i=Math.max(0,Math.min(values.length-1,index)),value=values[i],start=+el.dataset.start,end=+el.dataset.end,min=+el.dataset.min,max=+el.dataset.max,x=6+i/(values.length-1)*788,y=8+(1-(value-min)/(max-min))*205;el.dataset.index=i;const line=el.querySelector('.chart-crosshair'),point=el.querySelector('.chart-point'),tip=el.querySelector('.chart-tooltip');line.setAttribute('x1',x);line.setAttribute('x2',x);line.setAttribute('visibility','visible');point.setAttribute('cx',x);point.setAttribute('cy',y);point.setAttribute('visibility','visible');tip.hidden=false;tip.style.left=Math.max(0,Math.min(el.clientWidth-190,x/800*el.clientWidth))+'px';tip.innerHTML='<small>SCENARIO STEP '+num(start+(end-start)*i/(values.length-1),2)+'</small><strong>'+money(value)+' / share</strong><span>'+pct((value/values[0]-1)*100)+' in selected range</span>';}
function inspectPointer(e){const el=e.target.closest('.chart-wrap');if(!el)return;const rect=el.getBoundingClientRect();inspectChart(el,Math.round((e.clientX-rect.left)/rect.width*(el.dataset.values.split(',').length-1)));}
document.addEventListener('pointermove',inspectPointer);document.addEventListener('pointerdown',inspectPointer);
document.addEventListener('pointerout',e=>{const el=e.target.closest('.chart-wrap');if(!el||el.contains(e.relatedTarget))return;el.querySelector('.chart-tooltip').hidden=true;el.querySelector('.chart-crosshair').setAttribute('visibility','hidden');el.querySelector('.chart-point').setAttribute('visibility','hidden');});
document.addEventListener('keydown',e=>{const el=e.target.closest('.chart-wrap');if(!el||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const last=el.dataset.values.split(',').length-1;inspectChart(el,e.key==='Home'?0:e.key==='End'?last:(+(el.dataset.index||last))+(e.key==='ArrowRight'?1:-1));});
